function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').style.display='none',4500)}
function snapshot(){history.push(JSON.stringify(boxes));if(history.length>40)history.shift()}
function bounds(b){b.w=Math.min(img.width,Math.max(10,b.w));b.h=Math.min(img.height,Math.max(10,b.h));b.x=Math.max(0,Math.min(img.width-b.w,b.x));b.y=Math.max(0,Math.min(img.height-b.h,b.y));return b}
function size(){let w=num('cw',10,img?.width||10000),h=num('ch',10,img?.height||10000),r=Number($('ratio').value);if(r)h=w/r;if(img){let f=Math.min(1,img.width/w,img.height/h);w*=f;h*=f}return {w,h}}
function fit(){if(!img)return;scale=$('zoom').value==='fit'?Math.min(1,($('viewport').clientWidth-60)/img.width,($('viewport').clientHeight-60)/img.height):Number($('zoom').value);scale=Math.max(.02,scale);$('stage').style.width=img.width*scale+'px';$('stage').style.height=img.height*scale+'px';render(false)}
function filename(i){let prefix=$('prefix').value.trim().replace(/[<>:"/\\|?*\x00-\x1f]/g,'_')||'이모티콘';return prefix+'_'+String(num('start',0,999999)+i).padStart(2,'0')+'.'+($('format').value==='jpeg'?'jpg':$('format').value)}
function crop(b,w,h){const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');if($('bg').value==='white'||$('format').value==='jpeg'){ctx.fillStyle='white';ctx.fillRect(0,0,w,h)}ctx.imageSmoothingQuality='high';let dw=w,dh=h;const mode=$('outputMode').value==='custom'&&!$('outputLinked').checked?$('fit').value:'contain';if(mode!=='stretch'){let f=mode==='contain'?Math.min(w/b.w,h/b.h):Math.max(w/b.w,h/b.h);dw=b.w*f;dh=b.h*f}ctx.drawImage(img,b.x,b.y,b.w,b.h,(w-dw)/2,(h-dh)/2,dw,dh);return c}
function previews(){const p=$('previews');p.replaceChildren();if(!boxes.length){p.innerHTML='<div class="previewempty">영역을 추가하면 여기에서 미리 볼 수 있어요.</div>';return}boxes.forEach((b,i)=>{const btn=document.createElement('button');btn.className='thumb'+(i===selected?' active':'');btn.title=filename(i)+' · 클릭하여 영역 선택';const {w,h}=getOutputSize(b),f=Math.min(160/w,160/h);btn.append(crop(b,Math.max(1,Math.round(w*f)),Math.max(1,Math.round(h*f))));const label=document.createElement('small');label.textContent=filename(i)+' · '+w+' × '+h+' px';btn.title+=' · '+w+' × '+h+' px';const badge=document.createElement('em');badge.textContent=String(i+1).padStart(2,'0');btn.append(badge,label);btn.onclick=()=>{selected=i;render(false);previews();$('boxes').children[i]?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'})};p.append(btn)})}
function render(withPreview=true){updateOutputUI();$('boxes').replaceChildren();boxes.forEach((b,i)=>{const el=document.createElement('div');el.className='box'+(selected===i?' selected':'');Object.assign(el.style,{left:b.x*scale+'px',top:b.y*scale+'px',width:b.w*scale+'px',height:b.h*scale+'px'});el.innerHTML='<span class="num">'+String(i+1).padStart(2,'0')+'</span><span class="handle"></span>';el.onpointerdown=e=>{e.preventDefault();snapshot();selected=i;drag={i,startX:e.clientX,startY:e.clientY,b:{...b},resize:e.target.classList.contains('handle')};$('viewport').setPointerCapture(e.pointerId);render(false)};$('boxes').append(el)});$('count').textContent=boxes.length+'개 영역';$('pc').textContent=boxes.length;$('exportcount').textContent=boxes.length+'개의 그림이 준비되었어요';$('filename').textContent='파일명 예시: '+filename(0);if(withPreview)previews()}
$('viewport').onpointermove=e=>{if(!drag)return;const dx=(e.clientX-drag.startX)/scale,dy=(e.clientY-drag.startY)/scale;const b={...drag.b};if(drag.resize){b.w=Math.max(10,Math.min(img.width-b.x,b.w+dx));b.h=Math.max(10,Math.min(img.height-b.y,b.h+dy));const r=Number($('ratio').value);if(r){b.h=b.w/r;if(b.h>img.height-b.y){b.h=img.height-b.y;b.w=b.h*r}}}else{b.x+=dx;b.y+=dy}boxes[drag.i]=bounds(b);render(false)};
function endDrag(){if(drag){drag=null;previews()}}$('viewport').onpointerup=endDrag;$('viewport').onpointercancel=endDrag;
async function load(file){if(!file)return;if(!file.type.startsWith('image/'))return toast('이미지 파일을 선택해 주세요.');const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{if(im.width*im.height>100000000){URL.revokeObjectURL(url);return toast('이미지가 너무 큽니다. 1억 픽셀 이하로 줄여 주세요.')}img=im;boxes=[];history=[];selected=-1;$('source').src=url;$('stage').hidden=false;$('empty').style.display='none';$('info').textContent=file.name+' · '+im.width+' × '+im.height+' px';$('cw').value=Math.round(im.width/4);$('ch').value=Math.round(im.width/4);fit();render();toast('이미지를 불러왔어요. 기울기를 보정한 뒤 다음 단계로 이동하세요.');im.onload=null;};im.onerror=()=>{URL.revokeObjectURL(url);toast('이미지를 읽지 못했어요. PNG 또는 JPG 파일을 사용해 주세요.')};im.src=url}
$('file').onchange=e=>load(e.target.files[0]);$('pick').onclick=()=>$('file').click();['dragenter','dragover'].forEach(t=>$('drop').addEventListener(t,e=>{e.preventDefault();$('drop').classList.add('drag')}));['dragleave','drop'].forEach(t=>$('drop').addEventListener(t,e=>{e.preventDefault();$('drop').classList.remove('drag');if(t==='drop')load(e.dataTransfer.files[0])}));
function requireImage(){if(img)return true;toast('먼저 이미지를 불러와 주세요.');return false}
$('grid').onclick=()=>{if(!requireImage())return;const cols=num('cols',1,50)|0,rows=num('rows',1,50)|0;if(cols*rows>500)return toast('한 번에 최대 500개까지 만들 수 있어요.');snapshot();const s=size();boxes=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)boxes.push(bounds({x:(x+.5)*img.width/cols-s.w/2,y:(y+.5)*img.height/rows-s.h/2,...s}));selected=0;render();toast(boxes.length+'개의 영역을 배치했어요. 드래그해서 칸에 맞춰 주세요.')};
$('add').onclick=()=>{if(!requireImage())return;if(boxes.length>=500)return toast('최대 500개까지 추가할 수 있어요.');snapshot();const s=size(),prev=boxes[selected];boxes.push(bounds({x:prev?prev.x+20:img.width/2-s.w/2,y:prev?prev.y+20:img.height/2-s.h/2,...s}));selected=boxes.length-1;render()};
$('size').onclick=()=>{if(!requireImage())return;snapshot();const s=size();boxes=boxes.map(b=>bounds({...b,x:b.x+(b.w-s.w)/2,y:b.y+(b.h-s.h)/2,...s}));render();toast('모든 영역의 크기를 같게 맞췄어요.')};$('ratio').onchange=()=>{const r=Number($('ratio').value);if(r)$('ch').value=Math.round(num('cw',10,10000)/r)};$('cw').onchange=$('ratio').onchange;$('ch').onchange=()=>{const r=Number($('ratio').value);if(r)$('cw').value=Math.round(num('ch',10,10000)*r)};
$('undo').onclick=()=>{if(history.length){boxes=JSON.parse(history.pop());selected=Math.min(selected,boxes.length-1);render()}};$('clear').onclick=()=>{if(!boxes.length)return;snapshot();boxes=[];selected=-1;render()};$('zoom').onchange=fit;window.addEventListener('resize',fit);
document.addEventListener('keydown',e=>{if(typeof correctionBusy!=='undefined'&&correctionBusy)return;if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||selected<0||!boxes[selected])return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();snapshot();boxes.splice(selected,1);selected=Math.min(selected,boxes.length-1);render()}const dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(dirs[e.key]){e.preventDefault();snapshot();const b=boxes[selected],d=dirs[e.key],step=e.shiftKey?10:1;b.x+=d[0]*step;b.y+=d[1]*step;bounds(b);render()}});
['prefix','start','format','fit','bg'].forEach(id=>$(id).addEventListener('change',()=>render()));
function save(blob,name){const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
async function exportBlobs(){for(const b of boxes){const {w,h}=getOutputSize(b);checkOutputSize(w,h)}const files=[];for(let i=0;i<boxes.length;i++){toast('그림 저장 준비 중 · '+(i+1)+' / '+boxes.length);const {w,h}=getOutputSize(boxes[i]);const c=crop(boxes[i],w,h);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/'+$('format').value,.95));if(!blob)throw Error('이미지 변환에 실패했어요.');const ext=blob.type==='image/png'?'png':blob.type==='image/jpeg'?'jpg':'webp';files.push({name:filename(i).replace(/\.[^.]+$/,'.'+ext),blob});c.width=1;c.height=1;await new Promise(r=>setTimeout(r,0))}return files}
const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});function crc32(data){let n=0xffffffff;for(const v of data)n=crcTable[(n^v)&255]^(n>>>8);return (n^0xffffffff)>>>0}
async function zip(files){let offset=0;const chunks=[],central=[];for(const f of files){const data=new Uint8Array(await f.blob.arrayBuffer()),name=new TextEncoder().encode(f.name),crc=crc32(data);const head=new Uint8Array(30+name.length),v=new DataView(head.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);head.set(name,30);chunks.push(head,data);const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=head.length+data.length}let len=central.reduce((a,c)=>a+c.length,0);const end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,len,true);v.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'})}
async function download(isZip){if(!boxes.length)return toast('저장할 영역을 먼저 만들어 주세요.');$('zip').disabled=$('individual').disabled=true;try{const files=await exportBlobs();if(isZip)save(await zip(files),filename(0).replace(/_\d+\.[^.]+$/,'.zip'));else{for(const f of files){save(f.blob,f.name);await new Promise(r=>setTimeout(r,200))}}toast(isZip?'ZIP 파일을 저장했어요.':'개별 저장을 시작했어요. 브라우저가 요청하면 여러 파일 다운로드를 허용해 주세요.')}catch(e){toast('저장하지 못했어요. 출력 크기를 줄여 다시 시도해 주세요.');console.error(e)}finally{$('zip').disabled=$('individual').disabled=false}}$('zip').onclick=()=>download(true);$('individual').onclick=()=>download(false);
$('outputMode').onchange=()=>{if($('outputMode').value==='custom'){const b=outputReference(),f=outputFactor();outputAnchor='w';outputCustomValue=Math.max(1,Math.round(b.w*f));$('ow').value=outputCustomValue;$('oh').value=Math.max(1,Math.round(b.h*f))}render()};
for(const id of ['outputScale','scaleFactor'])$(id).addEventListener('input',()=>render());
$('outputLinked').onchange=()=>{if($('outputLinked').checked){outputAnchor='w';outputCustomValue=num('ow',1,16384)}render()};
for(const [id,axis] of [['ow','w'],['oh','h']]){
  $(id).oninput=()=>{if($(id).value===''||Number($(id).value)<1)return;outputAnchor=axis;outputCustomValue=num(id,1,16384);render()};
  $(id).onchange=()=>{if($(id).value===''||Number($(id).value)<1)$(id).value=1;outputAnchor=axis;outputCustomValue=num(id,1,16384);render()};
}
$('help').onclick=()=>toast('① 학습지 업로드 → ② 비율·크기를 정하고 격자 배치 → ③ 영역을 드래그해 맞추기 → ④ 출력 설정 후 ZIP 저장. 모서리로 크기 조절, 방향키로 미세 이동, Delete로 삭제할 수 있어요.');
